export function getCartoSpread(slug: string): CartoSpread | null {
  return CARTO_SPREADS.find((spread) => spread.slug === slug) ?? null;
}

/** The spreads that need no premium feature. */
export const CARTO_FREE_SPREADS: CartoSpread[] = CARTO_SPREADS.filter((spread) => spread.free);

/** A playing-card spread slug, as saved in `tarot_readings.spread_type`. */
export function isCartoSpreadSlug(slug: string): boolean {
  return slug.startsWith('carto-');
}
